package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.client.ClientUiApi;
import dev.tacticalcombat.rules.srd.SrdAuthoring;
import dev.tacticalcombat.uiapi.*;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.PlayerSkinDrawer;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

/** One post-creation dashboard for library sources and authorized campaign copies. */
public final class CharacterDashboardScreen extends ManagementScreen {
    private final DashboardSource source;
    private DashboardModel.Tab tab=DashboardModel.Tab.OVERVIEW;
    private JsonObject character;
    private JsonObject active=new JsonObject();
    private String campaignName="",campaign="";
    private int spellLevel=-1;
    private RpgButton tabButton;
    public CharacterDashboardScreen(Screen parent,DashboardSource source){super("Character Dashboard",parent);this.source=source;}
    public static CharacterDashboardScreen library(Screen parent,String id){return new CharacterDashboardScreen(parent,new DashboardSource(true,id));}
    public static CharacterDashboardScreen campaign(Screen parent,String id){return new CharacterDashboardScreen(parent,new DashboardSource(false,id));}
    @Override protected UiLayout.Rect listBounds(){return DashboardModel.listArea(frame);}
    @Override protected void controls(){int y=frame.y()+frame.height()-30;button("‹","Previous dashboard tab",frame.x()+84,y,28,20,()->move(-1));tabButton=button(DashboardModel.title(tab),"Choose dashboard tab",frame.x()+118,y,Math.min(150,frame.width()-250),20,this::tabs);button("›","Next dashboard tab",frame.x()+274,y,28,20,()->move(1));}
    @Override protected void refresh(){if(busy)return;fresh=false;clearRows();if(source.library())read(source.read(),source.readArgs(),data->{character=data;active=new JsonObject();campaign="";campaignName="";display();});else read(ACTIVE,args(),a->{active=a;read(source.read(),source.readArgs(),data->{character=data;campaign=text(data,"campaign");read(CAMPAIGN_GET,args("campaign",campaign),c->{campaignName=text(c,"name");display();});});});}
    private void move(int amount){tab=DashboardModel.Tab.values()[Math.floorMod(tab.ordinal()+amount,DashboardModel.Tab.values().length)];display();}
    private void tabs(){client.setScreen(new ChoiceScreen(this,"Dashboard tabs",Arrays.stream(DashboardModel.Tab.values()).map(Enum::name).toList(),s->DashboardModel.title(DashboardModel.Tab.valueOf(s)),s->{tab=DashboardModel.Tab.valueOf(s);display();}));}
    private boolean combat(){return flag(active,"inCombat");}
    private boolean selected(){return source.character().equals(text(active,"character"))||source.character().equals(text(active,"boundCharacter"));}
    private boolean editable(){return DashboardModel.editable(character,source.library(),self(),combat());}
    private void display(){if(character==null)return;clearRows();if(tabButton!=null)tabButton.setMessage(net.minecraft.text.Text.literal(DashboardModel.title(tab)));info(text(character,"name"),DashboardModel.header(character,source.library(),selected(),combat()));info("Editing state",DashboardModel.restriction(character,source.library(),self(),combat()));switch(tab){case OVERVIEW->overview();case ABILITIES->abilities();case COMBAT->combatTab();case EQUIPMENT->equipment();case FEATURES->features();case SPELLS->spells();case DETAILS->details();case NOTES->notes();case MANAGE->manage();}}
    private void overview(){var xp=DashboardModel.xp(character.getAsJsonObject("sheet"));row("Level "+xp.level()+" progression",xp.label(),true,"",()->show(DashboardModel.Tab.DETAILS));for(var stat:DashboardModel.combat(character,source.library()))row(stat.label(),stat.value()+" · "+stat.authority(),true,"",()->show(DashboardModel.Tab.COMBAT));JsonObject trackers=section("trackers");manualOverview(trackers);for(var e:trackers.getAsJsonArray("resources")){var p=e.getAsJsonObject();valueTracker(text(p,"name"),RpgRecords.Action.RESOURCE,"trackers",text(p,"id"),0,p.get("current").getAsInt(),p.get("maximum").getAsInt(),editable()&&text(p,"status").equals("MANUAL"));}JsonObject inventory=section("inventory");long equipped=java.util.stream.StreamSupport.stream(inventory.getAsJsonArray("items").spliterator(),false).filter(e->flag(e.getAsJsonObject(),"equipped")).count();row("Equipment",equipped+" equipped · "+inventory.getAsJsonArray("items").size()+" sheet records",true,"",()->show(DashboardModel.Tab.EQUIPMENT));JsonObject features=section("features");long conditions=java.util.stream.StreamSupport.stream(features.getAsJsonArray("entries").spliterator(),false).filter(e->text(e.getAsJsonObject(),"kind").equals("CONDITION")).count();row("Features, feats and conditions",features.getAsJsonArray("entries").size()+" entries · "+conditions+" recorded conditions · effects labelled by status",true,"",()->show(DashboardModel.Tab.FEATURES));for(var e:features.getAsJsonArray("resources")){var p=e.getAsJsonObject();valueTracker(text(p,"name"),RpgRecords.Action.RESOURCE,"features",text(p,"id"),0,p.get("current").getAsInt(),p.get("maximum").getAsInt(),editable()&&text(p,"status").equals("MANUAL"));}JsonObject spells=section("spellbook");row("Spellbook",spells.getAsJsonArray("selections").size()+" known/custom references · "+spells.getAsJsonArray("slots").size()+" manual slot pools",true,"",()->show(DashboardModel.Tab.SPELLS));}
    private void manualOverview(JsonObject t){boolean edit=editable();row("Inspiration",flag(t,"inspiration")?"Inspired · manual tracker":"Not inspired · manual tracker",edit,restriction(),()->manual(new RpgRecords.Change(RpgRecords.Action.INSPIRATION,"trackers","",0,flag(t,"inspiration")?0:1)));row("Death saves",t.get("deathSuccesses").getAsInt()+" successes · "+t.get("deathFailures").getAsInt()+" failures · manual only",edit,restriction(),()->show(DashboardModel.Tab.COMBAT));row("Hit Dice",t.getAsJsonArray("hitDice").size()+" recorded pools",true,"",()->show(DashboardModel.Tab.COMBAT));}
    private void abilities(){for(var stat:DashboardModel.abilities(character))row(stat.label(),stat.value()+" · "+stat.authority(),true,"",()->{});for(var stat:DashboardModel.skills(character))row(stat.label(),stat.value()+" · "+stat.authority(),true,"",()->{});JsonObject p=section("proficiencies");for(String key:List.of("tools","languages"))row(Character.toUpperCase(key.charAt(0))+key.substring(1),DashboardModel.strings(p,key).isEmpty()?"None recorded":String.join(", ",DashboardModel.strings(p,key))+" · manual/informational",true,"",()->{});try{JsonObject d=SrdAuthoring.data(character.getAsJsonObject("sheet"));info("Armor proficiencies",join(d,"armor_proficiencies"));info("Weapon proficiencies",join(d,"weapon_proficiencies"));}catch(RuntimeException ignored){}row("Edit recorded proficiencies","Does not modify authoritative combat formulas",editable(),restriction(),()->client.setScreen(DashboardEditors.proficiencies(this,character,source)));row("Edit authoritative SRD scores",source.library()?"Uses the existing six-score editor":"Uses the established campaign server workspace",editable()&&text(character,"profile").equals("srd_5_1"),restriction(),()->{if(source.library())client.setScreen(new AbilityScoreScreen(this,character));else client.setScreen(new dev.tacticalcombat.client.ServerCharactersScreen(this,null));});}
    private void combatTab(){for(var stat:DashboardModel.combat(character,source.library()))info(stat.label(),stat.value()+" · "+stat.authority());JsonObject data=null;try{data=SrdAuthoring.data(character.getAsJsonObject("sheet"));}catch(RuntimeException ignored){}if(data!=null){info("Automated weapons",join(data,"weapons")+" · existing Phase 3 server attack authority");info("Armor",text(data,"armor")+(flag(data,"shield")?" + shield":"")+" · existing SRD codec");}info("Actions","Existing Phase 3 attack/movement controls are available through encounter controls.");info("Bonus actions / reactions","No separate automated catalog; inspect manually recorded features below.");JsonObject trackers=section("trackers");trackerRows(trackers);JsonObject features=section("features");for(var e:features.getAsJsonArray("entries")){var f=e.getAsJsonObject();if(text(f,"kind").equals("CONDITION"))info("Condition: "+text(f,"name"),text(f,"source")+" · "+text(f,"status")+" · not necessarily enforced");}row("Open encounter controls","Use existing verified combat actions; this dashboard creates no outcomes",!source.library(),source.library()?"Library sources are not active combatants":"",()->client.setScreen(new DestinationScreen(this,DestinationScreen.Destination.ENCOUNTERS)));}
    private void trackerRows(JsonObject t){boolean edit=editable();chooseTracker("Death-save successes",RpgRecords.Action.DEATH_SUCCESSES,t.get("deathSuccesses").getAsInt(),3,edit);chooseTracker("Death-save failures",RpgRecords.Action.DEATH_FAILURES,t.get("deathFailures").getAsInt(),3,edit);chooseTracker("Exhaustion",RpgRecords.Action.EXHAUSTION,t.get("exhaustion").getAsInt(),6,edit);int i=0;for(var e:t.getAsJsonArray("hitDice")){var h=e.getAsJsonObject();valueTracker("Hit Dice d"+h.get("sides").getAsInt(),RpgRecords.Action.HIT_DICE,"trackers","",i++,h.get("current").getAsInt(),h.get("maximum").getAsInt(),edit);}for(var e:t.getAsJsonArray("resources")){var p=e.getAsJsonObject();valueTracker(text(p,"name"),RpgRecords.Action.RESOURCE,"trackers",text(p,"id"),0,p.get("current").getAsInt(),p.get("maximum").getAsInt(),edit&&text(p,"status").equals("MANUAL"));}}
    private void equipment(){JsonObject inv=section("inventory");var items=new ArrayList<JsonObject>();for(var e:inv.getAsJsonArray("items"))items.add(e.getAsJsonObject());items.sort(Comparator.<JsonObject,Boolean>comparing(o->!flag(o,"equipped")).thenComparing(o->text(o,"name")));for(var item:items)row(text(item,"name"),item.get("quantity").getAsInt()+" · "+(flag(item,"equipped")?"equipped":"carried")+" · slot "+text(item,"slot")+" · sheet record only",true,"",()->{if(editable())client.setScreen(new WizardRecordsScreen(this,character,"inventory",source));else client.setScreen(new InfoScreen(this,text(item,"name"),"Read-only sheet inventory",item.toString()));});info("Currency",inv.get("platinum").getAsLong()+" pp · "+inv.get("gold").getAsLong()+" gp · "+inv.get("electrum").getAsLong()+" ep · "+inv.get("silver").getAsLong()+" sp · "+inv.get("copper").getAsLong()+" cp");row("Manage sheet inventory","Search, inspect, add, edit or remove manual records. No Minecraft item or combat equipment changes.",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"inventory",source)));}
    private void features(){JsonObject f=section("features");var entries=new ArrayList<JsonObject>();for(var e:f.getAsJsonArray("entries"))entries.add(e.getAsJsonObject());entries.sort(Comparator.comparing(o->text(o,"kind")+text(o,"source")+text(o,"name")));for(var e:entries){String uses=e.has("uses")&&!e.get("uses").isJsonNull()?" · usage pool recorded":"";row(text(e,"name"),text(e,"kind")+" · "+text(e,"source")+" · "+text(e,"status")+uses+" · "+shorten(text(e,"description")),true,"",()->{if(editable())client.setScreen(new WizardRecordsScreen(this,character,"features",source));else client.setScreen(new InfoScreen(this,text(e,"name"),"Read-only feature · no automation implied",e.toString()));});}for(var e:f.getAsJsonArray("resources")){var p=e.getAsJsonObject();valueTracker(text(p,"name"),RpgRecords.Action.RESOURCE,"features",text(p,"id"),0,p.get("current").getAsInt(),p.get("maximum").getAsInt(),editable()&&text(p,"status").equals("MANUAL"));}row("Manage features / feats","Manual and informational records; no mechanics are granted",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"features",source)));}
    private void spells(){JsonObject b=section("spellbook");info("Spellcasting summary",text(b,"recordedAbility")+" · save DC "+text(b,"recordedSaveDc")+" · attack "+text(b,"recordedAttackModifier")+" · recorded/manual");row("Level filter",spellLevel<0?"All spell levels":spellLevel==0?"Cantrips":"Level "+spellLevel,true,"",()->client.setScreen(new ChoiceScreen(this,"Spell level filter",java.util.stream.IntStream.rangeClosed(-1,9).mapToObj(Integer::toString).toList(),v->Integer.parseInt(v)<0?"All":Integer.parseInt(v)==0?"Cantrips":"Level "+v,v->{spellLevel=Integer.parseInt(v);display();})));var selections=new ArrayList<JsonObject>();for(var e:b.getAsJsonArray("selections"))selections.add(e.getAsJsonObject());selections.sort(Comparator.<JsonObject>comparingInt(s->{var d=definition(b,text(s,"spell"));return d==null?99:d.get("level").getAsInt();}).thenComparing(s->{var d=definition(b,text(s,"spell"));return d==null?text(s,"spell"):text(d,"name");}));for(var s:selections){var d=definition(b,text(s,"spell"));if(d!=null&&spellLevel>=0&&d.get("level").getAsInt()!=spellLevel)continue;String name=d==null?text(s,"spell"):text(d,"name");String detail=d==null?"Definition unavailable":((d.get("level").getAsInt()==0?"Cantrip":"Level "+d.get("level").getAsInt())+" · "+text(d,"school")+" · "+(flag(s,"alwaysPrepared")?"always prepared":flag(s,"prepared")?"prepared":flag(s,"known")?"known":"recorded")+" · "+text(d,"castingTime")+" · "+text(d,"range"));row(name,detail,true,"",()->{if(editable())client.setScreen(new WizardRecordsScreen(this,character,"spellbook",source));else client.setScreen(new InfoScreen(this,name,"Read-only custom spell · no Cast action",d==null?s.toString():d.toString()));});}int i=0;for(var e:b.getAsJsonArray("slots")){var s=e.getAsJsonObject();valueTracker("Level "+s.get("level").getAsInt()+" spell slots",RpgRecords.Action.SPELL_SLOT,"spellbook","",i++,s.get("current").getAsInt(),s.get("maximum").getAsInt(),editable());}info("Standard catalog","Empty and explicitly unavailable; custom definitions only. No Cast Spell action exists.");row("Manage custom spellbook","Search/filter custom records and preparation flags",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"spellbook",source)));}
    private void details(){JsonObject identity=section("identity"),progression=section("progression");for(String key:List.of("species","characterClass","subclass","background","alignment","age","height","appearance"))info(label(key),text(identity,key).isBlank()?"Not recorded":text(identity,key));var xp=DashboardModel.xp(character.getAsJsonObject("sheet"));info("Progression",xp.label());row("Edit identity and details","Canonical fields; campaign saves may invalidate approval under policy",editable(),restriction(),()->client.setScreen(DashboardEditors.identity(this,character,source)));row("Edit recorded progression","Informational only; does not level combat statistics",editable(),restriction(),()->client.setScreen(DashboardEditors.progression(this,character,source)));}
    private void notes(){JsonObject i=section("identity");for(String key:List.of("biography","personality","ideals","bonds","flaws"))info(label(key),text(i,key).isBlank()?"Not recorded":shorten(text(i,key)));row("Edit bounded narrative notes","No separate unlimited notes field exists; unsaved form text is retained",editable(),restriction(),()->client.setScreen(DashboardEditors.notes(this,character,source)));}
    private void manage(){if(source.library()){info("Personal library source",text(character,"stage")+" · revision "+revision(character));row("Open lifecycle and submission management","Validate, finalize, duplicate and submit independent copies",true,"",()->client.setScreen(new LibraryCharacterScreen(this,source.character())));for(var e:array(character,"submissions")){var c=e.getAsJsonObject();row(text(c,"campaignName"),flag(c,"approved")?"Campaign copy approved":"Campaign copy awaiting approval",true,"",()->client.setScreen(CharacterDashboardScreen.campaign(this,text(c,"id"))));}}else{info("Campaign",campaignName+" · "+(flag(character,"approved")?"approved":"awaiting approval")+" · "+(text(character,"bound").isEmpty()?"unbound":"bound"));info("Ownership / control","Owner: "+player(character,text(character,"owner"))+" · controller: "+player(character,text(character,"controller")));row("Open campaign character management","Approval, assignment, binding and source navigation",true,"",()->client.setScreen(new CampaignCharacterScreen(this,source.character())));row("Rest requests","Request Short/Long Rest or review existing state; recovery remains manual",true,"",()->client.setScreen(new RestScreen(this,campaign)));row("Recent activity","Bounded session history, permission-filtered by server",true,"",()->client.setScreen(new RecentActivityScreen(this,campaign)));}}
    private void show(DashboardModel.Tab next){tab=next;display();}
    private JsonObject section(String key){return SheetSections.read(character.getAsJsonObject("sheet"),key);}
    private String restriction(){return DashboardModel.restriction(character,source.library(),self(),combat());}
    private void manual(RpgRecords.Change change){if(!editable()){message=restriction();return;}mutate(MANUAL_UPDATE,source.manualArgs(character,change),data->{character=data;display();});}
    private void chooseTracker(String name,RpgRecords.Action action,int value,int max,boolean enabled){row(name,Integer.toString(value)+" · manual tracker",enabled,restriction(),()->client.setScreen(new ChoiceScreen(this,name,java.util.stream.IntStream.rangeClosed(0,max).mapToObj(Integer::toString).toList(),v->v,v->manual(new RpgRecords.Change(action,"trackers","",0,Integer.parseInt(v))))));}
    private void valueTracker(String name,RpgRecords.Action action,String section,String key,int index,int value,int max,boolean enabled){row(name,value+" / "+max+" · manual resource",enabled,restriction(),()->{var field=List.of(new RecordFormScreen.Field("value","Current (0–"+max+")",Integer.toString(value),5));client.setScreen(new RecordFormScreen(this,name,source.read(),source.readArgs(),field,(state,v)->source.manualArgs(state,new RpgRecords.Change(action,section,key,index,WizardEditors.integer(v,"value",0,max))),MANUAL_UPDATE,data->client.setScreen(this),"Server-confirmed manual bookkeeping only; bound campaign updates are refused.").expected(character));});}
    private static String join(JsonObject o,String key){var v=new ArrayList<String>();for(var e:array(o,key))v.add(e.getAsString());return v.isEmpty()?"None":String.join(", ",v);}
    private static JsonObject definition(JsonObject b,String id){for(var e:b.getAsJsonArray("customDefinitions")){var d=e.getAsJsonObject();if(text(d,"id").equals(id))return d;}return null;}
    private static String label(String key){return switch(key){case "characterClass"->"Class";default->Character.toUpperCase(key.charAt(0))+key.substring(1);};}
    private static String shorten(String value){return value.length()>140?value.substring(0,137)+"…":value;}
    @Override protected void content(DrawContext g,int mx,int my,float delta){if(character==null||frame.height()<190)return;int x=frame.x()+12,y=frame.y()+61,w=frame.width()-24;RpgTheme.panel(g,x,y,w,39,RpgTheme.PANEL,false);boolean own=source.library()||text(character,"owner").equals(self());if(client.player!=null&&own)PlayerSkinDrawer.draw(g,client.player.getSkinTextures(),x+5,y+4,30);else RpgTheme.text(g,textRenderer,"REMOTE",x+4,y+15,36,RpgTheme.MUTED);RpgTheme.text(g,textRenderer,text(character,"name"),x+42,y+5,w-48,RpgTheme.GOLD);RpgTheme.text(g,textRenderer,DashboardModel.title(tab)+" · "+profile(text(character,"profile"))+(campaignName.isBlank()?"":" · "+campaignName),x+42,y+19,w-48,RpgTheme.MUTED);var xp=DashboardModel.xp(character.getAsJsonObject("sheet"));int bx=x+w-116,by=y+30,bw=110;g.fill(bx,by,bx+bw,by+4,0xFF30343B);g.fill(bx,by,bx+(int)(bw*xp.fraction()),by+4,RpgTheme.GOLD);}
    @Override protected int statusWidth(){return Math.max(40,frame.width()-320);}
}
